-- Backup generated on 2026-10-25 20:32:53

CREATE OR REPLACE FUNCTION public.fn_add_platform_branch(p_branch_id uuid, p_organization_id uuid, p_name character varying, p_location character varying)  RETURNS TABLE(id uuid, organization_id uuid, name character varying, location character varying, is_active boolean, created_at timestamp with time zone, organization_name character varying, effective_location text, classrooms_count integer, children_count integer)  LANGUAGE plpgsql AS $function$ DECLARE     v_tenant_id UUID;     v_org_name VARCHAR; BEGIN     SELECT tenant_id, o.name INTO v_tenant_id, v_org_name      FROM organizations o      WHERE o.id = p_organization_id;      IF v_tenant_id IS NULL THEN         v_tenant_id := p_organization_id;     END IF;      INSERT INTO branches (id, tenant_id, organization_id, name, location, is_active)     VALUES (p_branch_id, v_tenant_id, p_organization_id, p_name, p_location, TRUE);      RETURN QUERY     SELECT          p_branch_id,         p_organization_id,         p_name,         p_location,         TRUE,         NOW(),         COALESCE(v_org_name, 'Organization'),         COALESCE(p_location, 'Location unspecified'),         0::int,         0::int; END; $function$ ;
